{
  "explanation": "A Galton board (bean machine) drops balls through rows of pegs; at each peg a ball bounces left or right with fixed probability p. After n rows the ball lands in one of n+1 bins, and the bin index equals the number of right turns — a Binomial(n, p) random variable. With many balls the histogram converges to the binomial probabilities, and for large n it looks like a bell curve (Central Limit Theorem).",
  "manimCode": "const n = 8;
const spacing = 0.55;
const ySpacing = 0.38;
const topY = 2.8;
const boardX = -0.8;
const binBaseY = topY - n * ySpacing - 0.25;
const maxBarH = 2.15;
let pRight = 0.5;
const binCounts = Array(n + 1).fill(0);
let totalBalls = 0;
let busy = false;
let bars = [];
let expectedLines = [];
let expectedDots = [];

function binomCoeff(nn, k) {
  if (k < 0 || k > nn) return 0;
  let r = 1;
  for (let i = 0; i < k; i++) r = r * (nn - i) / (i + 1);
  return r;
}

const title = new Text({ text: 'Galton Board', color: WHITE, fontSize: 32 });
title.moveTo([-0.8, 3.65, 0]);
scene.add(title);

const subtitle = new Text({ text: 'Binomial distribution from random bounces', color: GRAY, fontSize: 18 });
subtitle.moveTo([-0.8, 3.2, 0]);
scene.add(subtitle);

const formula = new MathTex({ latex: 'P(K=k)=\\binom{n}{k}p^k(1-p)^{n-k}' });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([4.0, 3.4, 0]);
scene.add(formula);

let countLabel = new Text({ text: 'Balls: 0', color: YELLOW, fontSize: 22 });
countLabel.moveTo([4.0, 2.7, 0]);
scene.add(countLabel);

function refreshCount() {
  const pos = countLabel.getCenter();
  scene.remove(countLabel);
  countLabel = new Text({ text: 'Balls: ' + totalBalls, color: YELLOW, fontSize: 22 });
  countLabel.moveTo(pos);
  scene.add(countLabel);
}

const pegs = [];
for (let r = 0; r < n; r++) {
  for (let k = 0; k <= r; k++) {
    const x = boardX + (k - r / 2) * spacing;
    const y = topY - r * ySpacing;
    const peg = new Circle({ radius: 0.07, color: BLUE_B });
    peg.setFill(BLUE_B, 1);
    peg.setStrokeWidth(0);
    peg.moveTo([x, y, 0]);
    pegs.push(peg);
  }
}
scene.add(...pegs);

const funnelL = new Line({
  start: [boardX - 0.35, topY + 0.55, 0],
  end: [boardX - 0.08, topY + 0.15, 0],
  color: GRAY
});
const funnelR = new Line({
  start: [boardX + 0.35, topY + 0.55, 0],
  end: [boardX + 0.08, topY + 0.15, 0],
  color: GRAY
});
scene.add(funnelL, funnelR);

const walls = [];
for (let i = 0; i <= n + 1; i++) {
  const x = boardX + (i - 0.5 - n / 2) * spacing;
  const wall = new Line({
    start: [x, binBaseY, 0],
    end: [x, binBaseY + 0.35, 0],
    color: GRAY
  });
  walls.push(wall);
}
const baseLine = new Line({
  start: [boardX - (n / 2 + 0.5) * spacing, binBaseY, 0],
  end: [boardX + (n / 2 + 0.5) * spacing, binBaseY, 0],
  color: GRAY
});
scene.add(...walls, baseLine);

for (let i = 0; i <= n; i++) {
  const x = boardX + (i - n / 2) * spacing;
  const lab = new Text({ text: String(i), color: GRAY, fontSize: 14 });
  lab.moveTo([x, binBaseY - 0.28, 0]);
  scene.add(lab);
}

const binAxisLabel = new Text({ text: '# right bounces', color: GRAY, fontSize: 14 });
binAxisLabel.moveTo([boardX, binBaseY - 0.55, 0]);
scene.add(binAxisLabel);

const legendObs = new Text({ text: '■ observed', color: BLUE, fontSize: 16 });
legendObs.moveTo([4.0, 2.2, 0]);
const legendExp = new Text({ text: '● binomial theory', color: RED, fontSize: 16 });
legendExp.moveTo([4.0, 1.85, 0]);
scene.add(legendObs, legendExp);

function updateBars() {
  for (const b of bars) scene.remove(b);
  bars = [];
  const maxC = Math.max(...binCounts, 1);
  for (let i = 0; i <= n; i++) {
    const h = (binCounts[i] / maxC) * maxBarH;
    if (binCounts[i] === 0) continue;
    const x = boardX + (i - n / 2) * spacing;
    const hh = Math.max(h, 0.04);
    const bar = new Rectangle({
      width: spacing * 0.8,
      height: hh,
      color: BLUE
    });
    bar.setFill(BLUE, 0.85);
    bar.setStrokeWidth(1);
    bar.moveTo([x, binBaseY + hh / 2, 0]);
    bars.push(bar);
    scene.add(bar);
  }
}

function updateExpected() {
  for (const e of expectedLines) scene.remove(e);
  for (const d of expectedDots) scene.remove(d);
  expectedLines = [];
  expectedDots = [];
  if (totalBalls < 1) return;
  const maxC = Math.max(...binCounts, 1);
  const pts = [];
  for (let k = 0; k <= n; k++) {
    const pk = binomCoeff(n, k) * Math.pow(pRight, k) * Math.pow(1 - pRight, n - k);
    const expected = totalBalls * pk;
    const h = (expected / maxC) * maxBarH;
    const x = boardX + (k - n / 2) * spacing;
    const y = binBaseY + h;
    pts.push([x, y, 0]);
    const dot = new Dot({ point: [x, y, 0], color: RED });
    expectedDots.push(dot);
    scene.add(dot);
  }
  for (let i = 0; i < pts.length - 1; i++) {
    const ln = new Line({ start: pts[i], end: pts[i + 1], color: RED });
    ln.setStrokeWidth(2);
    expectedLines.push(ln);
    scene.add(ln);
  }
}

function simulatePath() {
  let rights = 0;
  for (let r = 0; r < n; r++) {
    if (Math.random() < pRight) rights++;
  }
  return rights;
}

async function dropBallAnimated() {
  if (busy) return;
  busy = true;
  let rights = 0;
  const ball = new Circle({ radius: 0.09, color: YELLOW });
  ball.setFill(YELLOW, 1);
  ball.setStrokeWidth(0);
  ball.moveTo([boardX, topY + 0.5, 0]);
  scene.add(ball);

  let cx = boardX;
  let cy = topY + 0.5;

  for (let r = 0; r < n; r++) {
    const pegX = boardX + (rights - r / 2) * spacing;
    const pegY = topY - r * ySpacing;
    let dx = pegX - cx;
    let dy = pegY - cy;
    await scene.play(new Shift(ball, { direction: [dx, dy, 0] }));
    cx = pegX;
    cy = pegY;

    if (Math.random() < pRight) rights++;

    const midX = boardX + (rights - (r + 0.5) / 2) * spacing;
    const midY = topY - (r + 0.5) * ySpacing;
    dx = midX - cx;
    dy = midY - cy;
    await scene.play(new Shift(ball, { direction: [dx, dy, 0] }));
    cx = midX;
    cy = midY;
  }

  const finalX = boardX + (rights - n / 2) * spacing;
  const finalY = binBaseY + 0.2;
  const dx = finalX - cx;
  const dy = finalY - cy;
  await scene.play(new Shift(ball, { direction: [dx, dy, 0] }));
  await scene.wait(0.08);
  scene.remove(ball);

  binCounts[rights]++;
  totalBalls++;
  updateBars();
  updateExpected();
  refreshCount();
  busy = false;
}

function dropManyInstant(count) {
  for (let i = 0; i < count; i++) {
    const rights = simulatePath();
    binCounts[rights]++;
    totalBalls++;
  }
  updateBars();
  updateExpected();
  refreshCount();
}

function resetBoard() {
  for (let i = 0; i <= n; i++) binCounts[i] = 0;
  totalBalls = 0;
  updateBars();
  updateExpected();
  refreshCount();
}

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addButton({
  label: 'Drop 1 ball',
  onClick: () => { dropBallAnimated(); }
});
controls.addButton({
  label: 'Drop 25 balls',
  onClick: () => {
    if (busy) return;
    dropManyInstant(25);
  }
});
controls.addButton({
  label: 'Drop 100 balls',
  onClick: () => {
    if (busy) return;
    dropManyInstant(100);
  }
});
controls.addSlider({
  label: 'P(right)',
  min: 0.15,
  max: 0.85,
  value: 0.5,
  step: 0.05,
  onChange: (val) => {
    pRight = val;
    updateExpected();
  }
});
controls.addButton({
  label: 'Reset',
  onClick: () => { resetBoard(); }
});

await scene.wait(0.4);
await dropBallAnimated();
await dropBallAnimated();
await dropBallAnimated();
dropManyInstant(80);

await scene.wait(999999);"
}

